#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""7-ingilizce-14 özel vektörel görselleri (6 bölüm, zengin SVG)."""

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING THE FREQUENCY OF ACTIONS IN WILDLIFE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Adverbs of Frequency (Sıklık Zarfları)</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• Always (%100) : Her zaman / Daima</text>\n  <text x="40" y="120" font-size="11.5" fill="#334155">• Usually / Generally (%80) : Genellikle</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• Often / Frequently (%60) : Sık sık</text>\n  <text x="40" y="164" font-size="11.5" fill="#334155">• Sometimes (%40) : Bazen / Ara sıra</text>\n  <text x="40" y="186" font-size="11.5" fill="#334155">• Rarely / Seldom (%10) : Nadiren</text>\n  <text x="40" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">• Never (%0) : Asla / Hiçbir zaman</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Wild Animals Habits (Doğal Alışkanlıklar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Lions always hunt other animals (Carnivores).</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Owls usually hunt at night and sleep during the day.</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• Bears often eat both meat and plants (Omnivores).</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• Elephants never eat meat; they eat leaves (Herbivores).</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• Question: How often do polar bears hunt seals?</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Subject + Adverb + Verb (Simple Present)</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING THE FREQUENCY OF ACTIONS IN WILDLIFE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Adverbs of Frequency (Sıklık Zarfları)</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• Always (%100) : Her zaman / Daima</text>\n  <text x="40" y="120" font-size="11.5" fill="#334155">• Usually / Generally (%80) : Genellikle</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• Often / Frequently (%60) : Sık sık</text>\n  <text x="40" y="164" font-size="11.5" fill="#334155">• Sometimes (%40) : Bazen / Ara sıra</text>\n  <text x="40" y="186" font-size="11.5" fill="#334155">• Rarely / Seldom (%10) : Nadiren</text>\n  <text x="40" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">• Never (%0) : Asla / Hiçbir zaman</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Wild Animals Habits (Doğal Alışkanlıklar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Lions always hunt other animals (Carnivores).</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Owls usually hunt at night and sleep during the day.</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• Bears often eat both meat and plants (Omnivores).</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• Elephants never eat meat; they eat leaves (Herbivores).</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• Question: How often do polar bears hunt seals?</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Subject + Adverb + Verb (Simple Present)</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE INQUIRIES ABOUT WILD ANIMALS</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Key Question Patterns (Soru Kalıpları)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Where do they live? (Habitat: Jungle, Desert, Ocean)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• What do they eat / prey on? (Diet: Meat, Grass)</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• How much do they weigh? (Weight: About 300 kg)</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• How tall / long are they? (Size: About 4 meters)</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• How long do they live? (Lifespan: About 25 years)</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">• Which class do they belong to? (Mammal/Reptile/Bird)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Animal Body Parts &amp; Classes</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Mammals: Fur, whiskers, paws, claws, tusks, trunk</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Birds: Feathers, wings, sharp beak, talons</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• Reptiles: Scales, poisonous / venomous teeth, tail</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• Fish: Fins, gills, sharp teeth (e.g., Sharks)</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• Herbivore (Otçul) | Carnivore (Etçil) | Omnivore (Hepçil)</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Animal Profile Cards Use These Questions</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE INQUIRIES ABOUT WILD ANIMALS</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Key Question Patterns (Soru Kalıpları)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Where do they live? (Habitat: Jungle, Desert, Ocean)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• What do they eat / prey on? (Diet: Meat, Grass)</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• How much do they weigh? (Weight: About 300 kg)</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• How tall / long are they? (Size: About 4 meters)</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• How long do they live? (Lifespan: About 25 years)</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">• Which class do they belong to? (Mammal/Reptile/Bird)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Animal Body Parts &amp; Classes</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Mammals: Fur, whiskers, paws, claws, tusks, trunk</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Birds: Feathers, wings, sharp beak, talons</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• Reptiles: Scales, poisonous / venomous teeth, tail</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• Fish: Fins, gills, sharp teeth (e.g., Sharks)</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• Herbivore (Otçul) | Carnivore (Etçil) | Omnivore (Hepçil)</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Animal Profile Cards Use These Questions</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE SUGGESTIONS: SHOULD &amp; SHOULDN\'T</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">What SHOULD We Do? (Tavsiyeler)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• We should protect wild animals and their habitats.</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• We should plant more trees and save forests.</text>\n  <text x="40" y="146" font-size="11" fill="#334155">• We should keep seas, rivers and nature clean.</text>\n  <text x="40" y="170" font-size="11" fill="#334155">• We should educate people about wildlife.</text>\n  <text x="40" y="194" font-size="11" fill="#334155">• We should support wildlife charities (like WWF).</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Should + Verb 1 (Yalın Fiil)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">What SHOULDN\'T We Do? (Uyarılar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• We shouldn\'t hunt animals for their fur, skin or tusks.</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• We shouldn\'t cut down trees (deforestation).</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• We shouldn\'t pollute the air, water and environment.</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• We shouldn\'t destroy animals\' natural habitats.</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• We shouldn\'t keep wild animals in cages or circuses.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Shouldn\'t + Verb 1 (Yalın Fiil)</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE SUGGESTIONS: SHOULD &amp; SHOULDN\'T</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">What SHOULD We Do? (Tavsiyeler)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• We should protect wild animals and their habitats.</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• We should plant more trees and save forests.</text>\n  <text x="40" y="146" font-size="11" fill="#334155">• We should keep seas, rivers and nature clean.</text>\n  <text x="40" y="170" font-size="11" fill="#334155">• We should educate people about wildlife.</text>\n  <text x="40" y="194" font-size="11" fill="#334155">• We should support wildlife charities (like WWF).</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Should + Verb 1 (Yalın Fiil)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">What SHOULDN\'T We Do? (Uyarılar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• We shouldn\'t hunt animals for their fur, skin or tusks.</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• We shouldn\'t cut down trees (deforestation).</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• We shouldn\'t pollute the air, water and environment.</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• We shouldn\'t destroy animals\' natural habitats.</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• We shouldn\'t keep wild animals in cages or circuses.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Shouldn\'t + Verb 1 (Yalın Fiil)</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TALKING ABOUT PAST EVENTS &amp; EXTINCT ANIMALS</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Extinct Animals (Soyu Tükenen Hayvanlar)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Dinosaurs: Became extinct 65 million years ago</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  because a giant meteor hit the Earth.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Dodo Bird: Lived on Mauritius Island; couldn\'t fly;</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  became extinct in 1681 because sailors overhunted it.</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• Tasmanian Tiger &amp; Mammoth &amp; Saber-toothed Tiger:</text>\n  <text x="40" y="200" font-size="11" fill="#334155">  Lived in the past, died out due to hunting &amp; climate.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Simple Past Tense Verbs in Unit 4</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• live -&gt; lived (yaşadı) | hunt -&gt; hunted (avladı)</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• die out -&gt; died out (nesli tükendi / yok oldu)</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• disappear -&gt; disappeared (ortadan kayboldu)</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• become -&gt; became extinct (soyu tükendi)</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• have -&gt; had (sahipti) | weigh -&gt; weighed (ağırlığındaydı)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Question: Why did they become extinct? (Did + V1)</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TALKING ABOUT PAST EVENTS &amp; EXTINCT ANIMALS</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Extinct Animals (Soyu Tükenen Hayvanlar)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Dinosaurs: Became extinct 65 million years ago</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  because a giant meteor hit the Earth.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Dodo Bird: Lived on Mauritius Island; couldn\'t fly;</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  became extinct in 1681 because sailors overhunted it.</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• Tasmanian Tiger &amp; Mammoth &amp; Saber-toothed Tiger:</text>\n  <text x="40" y="200" font-size="11" fill="#334155">  Lived in the past, died out due to hunting &amp; climate.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Simple Past Tense Verbs in Unit 4</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• live -&gt; lived (yaşadı) | hunt -&gt; hunted (avladı)</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• die out -&gt; died out (nesli tükendi / yok oldu)</text>\n  <text x="375" y="146" font-size="11" fill="#334155">• disappear -&gt; disappeared (ortadan kayboldu)</text>\n  <text x="375" y="170" font-size="11" fill="#334155">• become -&gt; became extinct (soyu tükendi)</text>\n  <text x="375" y="194" font-size="11" fill="#334155">• have -&gt; had (sahipti) | weigh -&gt; weighed (ağırlığındaydı)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Question: Why did they become extinct? (Did + V1)</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GIVING EXPLANATIONS AND REASONS (NEDEN VE SONUÇ)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Because / As (Çünkü)</text>\n  <text x="35" y="100" font-size="11" fill="#334155">• Kendisinden sonra tam</text>\n  <text x="35" y="118" font-size="11" fill="#334155">  bir sebep cümlesi alır:</text>\n  <text x="35" y="144" font-size="10.5" fill="#1e40af">  "Many species are in</text>\n  <text x="35" y="162" font-size="10.5" fill="#1e40af">   danger BECAUSE people</text>\n  <text x="35" y="180" font-size="10.5" fill="#1e40af">   destroy their habitats."</text>\n  <text x="125" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Because of + Noun (İsim)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. So / Therefore (Bu Yüzden)</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Kendisinden sonra sonuç</text>\n  <text x="260" y="118" font-size="11" fill="#334155">  veya tavsiye cümlesi alır:</text>\n  <text x="260" y="144" font-size="10.5" fill="#166534">  "Giant pandas are</text>\n  <text x="260" y="162" font-size="10.5" fill="#166534">   endangered, SO we should</text>\n  <text x="260" y="180" font-size="10.5" fill="#166534">   protect bamboo forests."</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Sebep + SO + Sonuç</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">3. For / To (-mek için)</text>\n  <text x="485" y="100" font-size="11" fill="#334155">• Amaç bildirir:</text>\n  <text x="485" y="124" font-size="10.5" fill="#9d174d">  "People hunted elephants</text>\n  <text x="485" y="142" font-size="10.5" fill="#9d174d">   FOR their ivory tusks."</text>\n  <text x="485" y="168" font-size="10.5" fill="#9d174d">  "Tigers hunt in order TO</text>\n  <text x="485" y="186" font-size="10.5" fill="#9d174d">   feed their cubs."</text>\n  <text x="575" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#be185d">For + Noun | To + Verb 1</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GIVING EXPLANATIONS AND REASONS (NEDEN VE SONUÇ)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Because / As (Çünkü)</text>\n  <text x="35" y="100" font-size="11" fill="#334155">• Kendisinden sonra tam</text>\n  <text x="35" y="118" font-size="11" fill="#334155">  bir sebep cümlesi alır:</text>\n  <text x="35" y="144" font-size="10.5" fill="#1e40af">  "Many species are in</text>\n  <text x="35" y="162" font-size="10.5" fill="#1e40af">   danger BECAUSE people</text>\n  <text x="35" y="180" font-size="10.5" fill="#1e40af">   destroy their habitats."</text>\n  <text x="125" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Because of + Noun (İsim)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. So / Therefore (Bu Yüzden)</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Kendisinden sonra sonuç</text>\n  <text x="260" y="118" font-size="11" fill="#334155">  veya tavsiye cümlesi alır:</text>\n  <text x="260" y="144" font-size="10.5" fill="#166534">  "Giant pandas are</text>\n  <text x="260" y="162" font-size="10.5" fill="#166534">   endangered, SO we should</text>\n  <text x="260" y="180" font-size="10.5" fill="#166534">   protect bamboo forests."</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Sebep + SO + Sonuç</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">3. For / To (-mek için)</text>\n  <text x="485" y="100" font-size="11" fill="#334155">• Amaç bildirir:</text>\n  <text x="485" y="124" font-size="10.5" fill="#9d174d">  "People hunted elephants</text>\n  <text x="485" y="142" font-size="10.5" fill="#9d174d">   FOR their ivory tusks."</text>\n  <text x="485" y="168" font-size="10.5" fill="#9d174d">  "Tigers hunt in order TO</text>\n  <text x="485" y="186" font-size="10.5" fill="#9d174d">   feed their cubs."</text>\n  <text x="575" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#be185d">For + Noun | To + Verb 1</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ENDANGERED SPECIES VS. EXTINCT SPECIES SUMMARY</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Endangered Animals (Nesli Tehlikede Olanlar)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Still alive today, but very few left in the wild!</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Examples: Giant Panda, Polar Bear, Caretta Caretta</text>\n  <text x="40" y="142" font-size="11" fill="#334155">  (Sea Turtle), Asian Elephant, Siberian Tiger,</text>\n  <text x="40" y="162" font-size="11" fill="#334155">  Mediterranean Monk Seal, Blue Whale, Gorilla.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Main Threats: Overhunting, habitat loss, global</text>\n  <text x="40" y="204" font-size="11" fill="#334155">  warming, deforestation, water &amp; air pollution.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Extinct Animals (Soyu Tükenmiş Olanlar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• No longer exist on Earth; all members died out!</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Examples: Tyrannosaurus Rex (Dinosaurs),</text>\n  <text x="375" y="142" font-size="11" fill="#334155">  Dodo Bird, Woolly Mammoth, Tasmanian Tiger,</text>\n  <text x="375" y="162" font-size="11" fill="#334155">  Saber-toothed Tiger (Smilodon), Passenger Pigeon.</text>\n  <text x="375" y="186" font-size="11" font-weight="bold" fill="#991b1b">• Key Action: Take precautions before endangered</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#991b1b">  animals become extinct!</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ENDANGERED SPECIES VS. EXTINCT SPECIES SUMMARY</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Endangered Animals (Nesli Tehlikede Olanlar)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Still alive today, but very few left in the wild!</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Examples: Giant Panda, Polar Bear, Caretta Caretta</text>\n  <text x="40" y="142" font-size="11" fill="#334155">  (Sea Turtle), Asian Elephant, Siberian Tiger,</text>\n  <text x="40" y="162" font-size="11" fill="#334155">  Mediterranean Monk Seal, Blue Whale, Gorilla.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Main Threats: Overhunting, habitat loss, global</text>\n  <text x="40" y="204" font-size="11" fill="#334155">  warming, deforestation, water &amp; air pollution.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Extinct Animals (Soyu Tükenmiş Olanlar)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• No longer exist on Earth; all members died out!</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• Examples: Tyrannosaurus Rex (Dinosaurs),</text>\n  <text x="375" y="142" font-size="11" fill="#334155">  Dodo Bird, Woolly Mammoth, Tasmanian Tiger,</text>\n  <text x="375" y="162" font-size="11" fill="#334155">  Saber-toothed Tiger (Smilodon), Passenger Pigeon.</text>\n  <text x="375" y="186" font-size="11" font-weight="bold" fill="#991b1b">• Key Action: Take precautions before endangered</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#991b1b">  animals become extinct!</text>\n</svg>'}

def uygula(v):
    for i, b in enumerate(v.get('bolumler', []), 1):
        if f'b{i}' in GORSELLER:
            b['gorsel'] = GORSELLER[f'b{i}']
